   ["3", "Los Siete Espíritus Rectores", "Creadores Supremos", "116:2.7"],
   ["4", "El Ser Supremo", "Personalización espiritual experiencial y foco del poder todopoderoso", "116:2.8, 116:2.12"],
   ["5", "El Actor Conjunto", "Deidad del Paraíso", "116:2.9"],
